<?php require_once __DIR__.'/../config.php';require_admin();$q=trim($_GET['q']??'');$status=$_GET['status']??'';$w=[];$args=[];if($q!==''){$w[]='(application_no LIKE ? OR company_name LIKE ? OR contact_name LIKE ? OR email LIKE ?)';$x="%$q%";$args=[$x,$x,$x,$x];}if(in_array($status,['pending','reviewing','more_info','approved','declined'],true)){$w[]='status=?';$args[]=$status;}$sql='SELECT * FROM applications'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY FIELD(status,"pending","reviewing","more_info","approved","declined"),created_at DESC';$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$counts=[];foreach(['pending','reviewing','more_info','approved','declined'] as $v){$x=db()->prepare('SELECT COUNT(*) c FROM applications WHERE status=?');$x->execute([$v]);$counts[$v]=(int)$x->fetch()['c'];}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PartnerHub Admin</title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin"><header class="admin-top"><a class="logo" href="../index.php"><span class="logo-mark">P</span>PartnerHub</a><div><span>Partner operations</span><a href="logout.php">Sign out</a></div></header><main class="admin-main"><div class="admin-heading"><div><span class="kicker">PARTNER OPERATIONS</span><h1>Applications</h1></div><a class="btn primary" href="../apply.php">New application ↗</a></div><div class="stats"><?php foreach($counts as $k=>$v):?><div><small><?=ucwords(str_replace('_',' ',$k))?></small><strong><?=$v?></strong></div><?php endforeach;?></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search company, applicant or email"><select name="status"><option value="">All statuses</option><?php foreach(array_keys($counts) as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select><button class="btn">Filter</button></form><section class="table"><div class="table-head"><span>APPLICATION</span><span>COMPANY</span><span>TYPE</span><span>STATUS</span><span>DATE</span></div><?php foreach($rows as $r):?><a class="table-row" href="view.php?id=<?=$r['id']?>"><b><?=e($r['application_no'])?></b><span><strong><?=e($r['company_name'])?></strong><small><?=e($r['contact_name'])?> · <?=e($r['email'])?></small></span><span><?=e($r['partner_type'])?></span><span class="pill pill-<?=e($r['status'])?>"><?=e(str_replace('_',' ',$r['status']))?></span><small><?=e(date('M j, Y',strtotime($r['created_at'])))?></small></a><?php endforeach;if(!$rows):?><div class="empty">No applications found.</div><?php endif;?></section></main></body></html>